-- Alarga los guiones de los Reels a 30–60 s en la tabla ya cargada.
-- Solo cambia las escenas (partes) de los reels; no toca caption, CTA, hashtags ni etapa.
-- Si editaste a mano las escenas de algún reel, esas ediciones se sobrescriben.

update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Antes de que digas una sola palabra, tu piel ya habló."],["p","4–13 s · Idea","Cómo duermes, cómo comes, cuánto estrés cargas… todo se nota en tu rostro. No es vanidad: es información que tu cuerpo te está dando."],["e","13–21 s · Lo que casi nadie te dijo","El problema es que a casi nadie le enseñaron a escucharla. Nos dijeron qué comprar, pero nunca cómo funciona la piel."],["e","21–32 s · Qué cambia cuando aprendes","Cuando entiendes lo que tu piel te dice, dejas de probar productos al azar. Empiezas a elegir con criterio y a cuidarla con calma, sin culpa y sin prisa.",9],["c","32–42 s · Cierre","Aquí voy a compartir, paso a paso, tips para aprender a leer tu piel. Sígueme para no perdértelos y cuéntame: ¿qué te dice la tuya hoy?"]]$j$::jsonb) where dia = 1 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Si tu piel es grasa, no te saltes este paso.",4],["p","4–14 s · El mito","Mito: “si brilla, no necesita hidratación”. Pero piel grasa no es lo mismo que piel hidratada, y confundirlas es uno de los errores más comunes.",4],["e","14–26 s · La verdad","Una piel grasa también puede estar deshidratada: le falta agua, aunque le sobre grasa. Y si la resecas de más con productos muy fuertes, puede responder produciendo todavía más grasa.",11],["e","26–35 s · Qué hacer","La clave es sencilla: una limpieza adecuada, una hidratación ligera, de textura fresca, y protector solar todos los días. Tres pasos, sin complicarte.",10],["c","35–40 s · Cierre","Equilibrio, no guerra contra tu piel. Sígueme y te desmiento más mitos del skincare.",1]]$j$::jsonb) where dia = 3 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–6 s · Gancho","A los 11 años me miré al espejo y sentí que nadie podía responder mis preguntas."],["p","6–17 s · La historia","Tuve acné severo durante años. Probé dermatólogos y tratamientos: mejoras temporales y recaídas que dolían más. Cada crema nueva era una esperanza, y cada recaída, una pequeña derrota."],["e","17–29 s · El giro","Hasta que entendí algo: nunca me faltó “la crema correcta”. Me faltó que alguien me enseñara cómo funciona mi piel. Empecé a estudiar, a preguntar y a observar con calma."],["e","29–39 s · Lo que cambió","Hoy no tengo una piel perfecta ni quiero vender esa idea. Lo que cambió fue mi forma de mirarme al espejo: con más paciencia y menos castigo."],["c","39–44 s · Cierre","Por eso existe Glow21. Si te identificas, sígueme y comenta “ESPEJO”."]]$j$::jsonb) where dia = 4 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","Seca y deshidratada no son lo mismo.",4],["p","3–16 s · La diferencia","La piel seca es un tipo de piel: produce poca grasa por naturaleza. La deshidratación es un estado: a tu piel le falta agua, y le puede pasar a cualquier tipo de piel.",3],["e","16–28 s · Cómo notarlo","Por eso una piel grasa también puede estar deshidratada. Las señales: se siente tirante, se ve opaca o sin confort, y a veces brilla y se irrita al mismo tiempo.",11],["e","28–37 s · Qué hacer","Una piel seca necesita ingredientes que aporten suavidad y grasas. Una deshidratada necesita agua y, sobre todo, proteger su barrera para no perderla.",13],["c","37–44 s · Cierre","Antes de comprar algo más, aprende a reconocer tu caso. Guarda este video y sígueme para más tips.",1]]$j$::jsonb) where dia = 6 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Probaste de todo… ¿y nadie te explicó cómo funciona tu piel?",3],["p","4–14 s · Problema","Cremas, sérums, tendencias de redes. Compras uno, luego otro, y sigues sin saber qué necesita tu piel de verdad. No es tu culpa: nadie nos lo enseñó.",15],["e","14–25 s · Lo que vas a aprender","En esta cuenta vamos a ver cómo funciona la piel, qué capas la forman, y por qué se ve distinta según cómo duermes, comes y manejas el estrés.",11],["e","25–33 s · Cómo lo vamos a hacer","También hablaremos de los enemigos invisibles de la piel y de la cosmética coreana, siempre en lenguaje sencillo y sin promesas milagro.",11],["c","33–38 s · Cierre","Sin tecnicismos y sin presión. Sígueme y aprendemos juntas.",1]]$j$::jsonb) where dia = 7 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Si tu piel se siente “chirriante de limpia”, ya te pasaste.",15],["p","4–13 s · El error","Esa tirantez después de lavarte no es limpieza profunda. Es tu barrera cutánea pidiendo ayuda, porque se quedó sin los aceites que la protegen.",3],["e","13–24 s · Por qué importa","Cuando la barrera se debilita, la piel pierde agua más rápido y se vuelve más sensible: se enrojece, arde o se siente rara con productos que antes toleraba.",11],["e","24–35 s · Qué hacer","Limpia con suavidad, mañana y noche. Agua tibia, sin tallar, y un limpiador que respete tu piel. Si te queda la cara tirante, ese producto no es para ti.",11],["c","35–42 s · Cierre","Más limpieza no es más salud. Cuéntame en comentarios: ¿a ti también te pasaba? Y sígueme para más tips.",18]]$j$::jsonb) where dia = 9 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–5 s · Gancho","Si solo vas a hacer una cosa por tu piel, que sea esta.",10],["p","5–16 s · Por qué","Los rayos UV son de los enemigos invisibles más constantes: te alcanzan aunque esté nublado, aunque estés junto a una ventana, y sus efectos se acumulan con los años.",15],["e","16–25 s · Cómo","Protector solar todos los días, en cantidad suficiente para cubrir bien rostro y cuello. Y reaplica si vas a estar al aire libre.",11],["e","25–35 s · El truco","El mejor protector es el que sí te gusta usar: elige una textura cómoda y úsala sin falta. La constancia importa más que la marca.",9],["c","35–43 s · Cierre","No es un paso opcional: es la base de cualquier rutina. ¿Ya lo usaste hoy? Cuéntame y sígueme para más tips.",9]]$j$::jsonb) where dia = 10 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","¿12 productos en tu baño y tu piel sigue igual?",3],["p","4–14 s · Idea","La cosmética coreana no se trata de tener más. Se trata de tener un sistema, y de saber para qué sirve cada cosa que te pones.",9],["e","14–23 s · Cómo funciona","Cada paso tiene un propósito: limpiar, equilibrar, nutrir y proteger. Si un producto no cumple ninguno de esos propósitos, sobra, aunque esté de moda.",11],["e","23–34 s · Tu tarea","Haz este ejercicio hoy: saca todos tus productos, ponlos sobre la cama y pregúntate qué hace cada uno. A los que no tengan una respuesta clara, dales un descanso.",11],["c","34–39 s · Cierre","Menos productos, más sistema. Cuéntame cuántos tienes y sígueme para armar tu rutina simple.",18]]$j$::jsonb) where dia = 12 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Esto es lo que vas a encontrar en esta cuenta.",2],["p","4–14 s · Cada semana","Cada semana, un tema: primero entender tu piel, luego cuidarla con una rutina simple, después nutrirla desde adentro, y por último entender la ciencia que hay detrás.",11],["e","14–24 s · Cómo lo hago","Sin promesas milagro, sin 12 productos y sin tecnicismos. Lo que busco es que tengas la información para decidir con criterio qué necesita tu piel.",9],["e","24–32 s · Qué más hay","Además habrá mitos desmentidos, trucos para leer etiquetas, mini retos y conversaciones sobre cómo nos vemos y cómo nos sentimos.",8],["c","32–37 s · Cierre","Sígueme para no perderte ningún tip. Y cuéntame qué te gustaría aprender primero.",1]]$j$::jsonb) where dia = 14 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Tu piel no vive aislada del resto de tu cuerpo.",8],["p","4–15 s · Idea","Lo que comes, cuánto duermes y cómo manejas el estrés se refleja en cómo se ve y se siente tu piel. Por dentro y por fuera, todo está conectado.",3],["e","15–23 s · Nutricosmética","Por eso trabajamos la nutricosmética: cuidarte también desde adentro, con buena alimentación y hábitos, como complemento de tu rutina, nunca como sustituto.",11],["e","23–34 s · Ejemplos","Más agua durante el día, frutas y verduras de colores, dormir lo suficiente y tomarte pausas cuando sientes estrés. Nada de esto es perfecto, pero sí es constante.",17],["c","34–41 s · Cierre","Empieza con algo simple hoy: un vaso de agua, una fruta más. Cuéntame qué hábito eliges y sígueme.",17]]$j$::jsonb) where dia = 15 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","Hay 5 enemigos de tu piel que ni ves.",15],["p","3–11 s · La lista","Uno: el estrés. Dos: el exceso de azúcar. Tres: los rayos UV. Cuatro: la contaminación. Cinco: la luz azul de las pantallas.",11],["e","11–22 s · Por qué importan","Son invisibles porque no los notas en el momento, pero su efecto se acumula con el tiempo y se refleja en cómo luce y se siente tu piel.",3],["e","22–30 s · Ojo","Esto no es para asustarte: es para que sepas dónde sí puedes ayudar a tu piel, con hábitos pequeños y constantes.",5],["e","30–42 s · Qué sí puedes hacer","Usa protector solar a diario, duerme lo que puedas, toma pausas para el estrés, limpia tu rostro al final del día y baja el brillo de las pantallas de noche.",10],["c","42–47 s · Cierre","Sígueme y te cuento cómo cuidarte de cada uno.",1]]$j$::jsonb) where dia = 17 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","Imagina tu piel como una ciudad.",3],["p","3–12 s · La analogía","Cada célula es una casa. Para que la ciudad funcione, las casas necesitan comunicarse: pasarse información y recursos, como vecinos que se coordinan.",11],["e","12–22 s · La idea","Cuando esa comunicación funciona bien, la ciudad prospera. Es una analogía para entender por qué importa cuidar el entorno en el que viven tus células.",13],["e","22–34 s · Qué significa para ti","Dormir bien, comer variado, protegerte del sol y manejar el estrés ayudan a que ese entorno esté en buenas condiciones. No es magia: es hábito, y se construye todos los días.",9],["c","34–39 s · Cierre","Ciencia sencilla, sin promesas médicas. Sígueme: vuelvo con más cada semana.",1]]$j$::jsonb) where dia = 18 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","Una rutina no es un producto. Es un sistema.",9],["p","3–10 s · La rutina","La rutina que recomendamos en Glow21 tiene 4 pasos: limpiador, tónico, loción y crema. Cuatro, no doce.",11],["e","10–18 s · El propósito","Cada paso cumple un propósito dentro del método: limpiar, equilibrar, nutrir y proteger. Si entiendes el para qué, ya no necesitas adivinar.",13],["e","18–27 s · Cómo empezar","No tienes que cambiarlo todo hoy. Empieza por revisar qué paso te falta y hazlo constante durante unas semanas antes de agregar algo nuevo.",13],["c","27–34 s · Cierre","El centro siempre es entender tu piel, no acumular productos. Sígueme y armamos tu rutina paso a paso.",1]]$j$::jsonb) where dia = 20 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","¿Por qué 21 días y no 7 ni 30?",3],["p","3–11 s · Idea","Porque los cambios reales no pasan en un día: pasan cuando repites pequeños actos de amor propio, una y otra vez.",8],["e","11–20 s · El punto de partida","21 días es un punto de partida para instalar un hábito. No es una meta mágica; la transformación continúa después, a tu ritmo.",11],["e","20–29 s · Cómo se ve","Puede ser tan simple como limpiar tu piel con calma, tomar agua y ponerte protector solar. Pequeñas acciones, todos los días, sin exigirte perfección.",17],["c","29–35 s · Cierre","No es una meta de perfección: es empezar. ¿Empezamos juntas? Sígueme y vamos paso a paso.",20]]$j$::jsonb) where dia = 22 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","Aprende a leer la etiqueta de tus productos en 30 segundos.",13],["p","4–13 s · Truco 1","Los ingredientes se enlistan de mayor a menor cantidad: los primeros son la base de la fórmula, así que ahí está lo más importante.",11],["e","13–23 s · Truco 2","Fíjate en para qué sirve cada ingrediente en tu piel, no en cuál suena a moda. Un nombre muy largo no significa que sea mejor ni peor.",13],["e","23–33 s · Truco 3","Si tu piel es sensible, busca fórmulas sencillas y prueba un producto nuevo a la vez, para saber con claridad cuál te cae bien o mal.",11],["c","33–38 s · Cierre","Leer ingredientes cambia cómo eliges. Guarda este video y sígueme para más trucos.",1]]$j$::jsonb) where dia = 25 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–4 s · Gancho","En Glow21 no vas a ver un antes y después milagroso.",4],["p","4–11 s · Honestidad","Y es a propósito. No prometemos eliminar arrugas ni borrar cicatrices, porque nadie puede prometerlo con honestidad.",8],["e","11–17 s · Lo que sí","Prometemos educación, hábitos y acompañamiento. Que entiendas tu piel antes de invertir en cualquier producto.",11],["e","17–26 s · Por qué","Porque la piel más hermosa no es la más perfecta: es la que refleja una vida vivida con conocimiento, bienestar y amor propio.",8],["c","26–31 s · Cierre","Si esa honestidad es lo que buscabas, sígueme: aquí hay educación, no milagros.",8]]$j$::jsonb) where dia = 26 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–3 s · Gancho","¿Qué te da pena preguntar sobre tu piel?",18],["p","3–13 s · Las dudas","Qué usar primero, si tu rutina está bien, si ese producto de moda de verdad sirve, o si lo que sientes en tu piel es normal.",14],["e","13–23 s · Aquí sin pena","Quiero que este sea un espacio sin juicios. No existen las preguntas tontas: casi siempre detrás de una duda hay algo que a nadie le explicaron.",18],["e","23–31 s · Cómo participar","Déjame tu pregunta en los comentarios o mándala por mensaje. Esta semana respondo las más repetidas, con calma y sin tecnicismos.",11],["c","31–36 s · Cierre","Déjalas en comentarios y sígueme para ver las respuestas.",1]]$j$::jsonb) where dia = 28 and data->>'f' = 'Reel';
update public.glow21_contenido set data = jsonb_set(data, '{partes}', $j$[["g","0–5 s · Gancho","Tu rutina de noche puede ser el mejor momento de tu día.",12],["p","5–14 s · El ritual","Apaga el celular un minuto. Limpia con calma, aplica tus productos pensando en algo que agradeces de ti, y respira profundo entre cada paso.",12],["e","14–22 s · Por qué ayuda","Convertir el cuidado en un ritual te baja el ritmo después del día, y vuelve constante algo que antes hacías con prisa.",20],["e","22–30 s · La idea","Creemos que una rutina de cuidado también puede ser un ritual de gratitud: un momento tuyo, sin exigencias ni comparaciones.",12],["c","30–35 s · Cierre","¿Qué agradeces hoy de ti? Cuéntamelo en comentarios y sígueme para más rituales.",18]]$j$::jsonb) where dia = 29 and data->>'f' = 'Reel';
